import Foundation

public enum CaptureBundleSchemaRegistry {
    /// Maps a logical bundle path to its published schema family.
    /// Frame descriptors live at evidence/frames/<frame-id>.json.
    /// RoomPlan payloads (roomplan/captured-room*.json) are opaque
    /// external authority payloads and deliberately have no family
    /// (#332): they are governed by media type plus lineage binding.
    public static func schemaName(forPath path: String) -> String? {
        switch path {
        case "advisory/operator-advisories.json":
            return "advisory-notes"
        case "annotations/authorities.json":
            return "authorities"
        case "annotations/entities.json":
            return "entities"
        case "annotations/measurements.json":
            return "measurements"
        case "annotations/authorities.json":
            return "authorities"
        case "quality/capture-quality.json":
            return "quality"
        case "session/room-reference-frame.json":
            return "room-reference-frame"
        case "session/room-field-datum.json":
            return "room-field-datum"
        case "annotations/opening-review.json":
            return "opening-review"
        case "derived/equipment-identity.json":
            return "equipment-identity"
        case "derived/geometry-candidates.json":
            return "derived-geometry-candidates"
        case "derived/segmentation-observations.json":
            return "segmentation-observations"
        case "evidence/reference-targets.json":
            return "reference-targets"
        case "evidence/reference-object-observations.json":
            return "reference-object-observations"
        case "manifest.json":
            return "manifest"
        case "mesh/anchors.json":
            return "mesh-anchors"
        case "quality/capture-advisory.json":
            return "capture-advisory"
        case "quality/capture-quality.json":
            return "quality"
        case "session/capabilities.json":
            return "capabilities"
        case "session/capture-configuration.json":
            return "capture-configuration"
        case "session/capture-session.json":
            return "session"
        case "session/capture-task-plan.json":
            return "capture-task-plan"
        case "session/connected-spaces.json":
            return "connected-spaces"
        case "session/field-notes.json":
            return "field-notes"
        case "session/coordinate-space-policy.json":
            return "coordinate-space-policy"
        case "session/device.json":
            return "device"
        case "session/room-reference-frame.json":
            return "room-reference-frame"
        case "session/task-plan-status.json":
            return "task-plan-status"
        case "session/revisit-flags.json":
            return "revisit-flags"
        case "session/revision-state.json":
            return "working-revision-state"
        case "session/timing.json":
            return "timing"
        case "verification/as-built.json":
            return "as-built"
        case "session/capture-strategy.json":
            return "capture-strategy"
        case "revision/intent.json":
            return "revision-intent"
        case "revision/registrations.json":
            return "cross-revision-registration"
        case "reference/plan-underlay.json":
            return "plan-underlay"
        case "derived/authority-dependencies.json":
            return "authority-dependencies"
        case "derived/operator-profiles.json":
            return "operator-profiles"
        case "derived/field-evidence.json":
            return "field-evidence"
        case "derived/instrument-profiles.json":
            return "instrument-profiles"
        case "derived/settings-observations.json":
            return "settings-observations"
        case "derived/wiring-routes.json":
            return "wiring-routes"
        default:
            let components = path.split(
                separator: "/",
                omittingEmptySubsequences: false
            )
            if components.count == 3,
               components[0] == "evidence",
               components[1] == "frames",
               components[2].hasSuffix(".json"),
               components[2].count > 5
            {
                return "frame"
            }
            return nil
        }
    }

    /// The published support matrix (#332): which payload versions each
    /// schema-owned family emits and reads, and which registry document
    /// key serves a given (family, version) pair.
    public static let supportMatrix: CapturePayloadSupportMatrix = {
        let value: CapturePayloadSupportMatrix
        do {
            value = try JSONDecoder().decode(
                CapturePayloadSupportMatrix.self,
                from: Data(supportMatrixJSON.utf8)
            )
        } catch {
            preconditionFailure(
                "embedded support matrix failed to decode: \(error)"
            )
        }
        precondition(
            value.schema == CapturePayloadSupportMatrix.schema,
            "embedded support matrix has wrong schema"
        )
        return value
    }()

    /// Resolves the registry document key that validates `path` at the
    /// payload's declared `schema_version`. Returns nil when the path
    /// is not schema-owned; throws `.unsupportedVersion` when the
    /// declared version is not one this build reads (#332).
    public static func schemaDocumentName(
        forPath path: String,
        payload: StrictJSONValue
    ) throws -> String? {
        guard let family = schemaName(forPath: path) else {
            return nil
        }
        guard let contract = supportMatrix.families[family] else {
            return family
        }
        if contract.external {
            return nil
        }
        if contract.unversioned {
            return contract.documents["unversioned"] ?? family
        }
        let declaredVersion = payload.member("schema_version")?
            .stringValue
        guard let document = supportMatrix.schemaDocumentName(
            family: family,
            version: declaredVersion
        ) else {
            throw JSONSchemaError.unsupportedPayloadVersion(
                family: family,
                version: declaredVersion ?? "missing",
                supported: contract.read
            )
        }
        return document
    }

    public static func compiledSchema(
        named name: String
    ) throws -> CompiledJSONSchema {
        let registry = try compiled.get()
        guard let schema = registry[name] else {
            throw JSONSchemaError.unknownSchema(name)
        }
        return schema
    }

    private static let compiled: Result<
        [String: CompiledJSONSchema],
        JSONSchemaError
    > = {
        do {
            var registry: [String: CompiledJSONSchema] = [:]
            for (name, source) in documents {
                let parsed = try StrictJSON.parse(Data(source.utf8))
                registry[name] = try JSONSchemaValidator.compile(parsed)
            }
            return .success(registry)
        } catch let error as JSONSchemaError {
            return .failure(error)
        } catch {
            return .failure(.invalidKeywordValue("schema document"))
        }
    }()

